// Pure Wikifactor snapshot contracts, chunking, and keyword ranking for RevAI.
// The snapshot itself is generated by `scripts/sync-revai-wikifactor.ts`.

export type WikifactorChunk = {
  heading: string | null
  text: string
}

export type WikifactorDoc = {
  /** Path inside federzimer/wikifactor, e.g. `playbooks/setup-spec.md`. */
  path: string
  title: string
  /** `accepted` = merged on the base ref; `draft` = only on an open branch. */
  status: "accepted" | "draft"
  branch: string | null
  chunks: WikifactorChunk[]
}

export type WikifactorCorpus = {
  generatedAt: string
  base: { ref: string; sha: string }
  drafts: Array<{ ref: string; sha: string }>
  docs: WikifactorDoc[]
}

export type WikifactorHit = {
  path: string
  title: string
  status: WikifactorDoc["status"]
  branch: string | null
  heading: string | null
  excerpt: string
  score: number
}

const MAX_CHUNK_CHARS = 2_400

/** Split a page on `##`/`###` headings, then cap long sections by paragraph. */
export function chunkWikifactorMarkdown(markdown: string): WikifactorChunk[] {
  const sections: WikifactorChunk[] = []
  let heading: string | null = null
  let buffer: string[] = []

  const flush = () => {
    const text = buffer.join("\n").trim()
    buffer = []
    if (!text) return
    if (text.length <= MAX_CHUNK_CHARS) {
      sections.push({ heading, text })
      return
    }
    let current = ""
    for (const paragraph of text.split(/\n{2,}/)) {
      if (current && current.length + paragraph.length > MAX_CHUNK_CHARS) {
        sections.push({ heading, text: current.trim() })
        current = ""
      }
      current += `${paragraph}\n\n`
    }
    if (current.trim()) sections.push({ heading, text: current.trim().slice(0, MAX_CHUNK_CHARS * 2) })
  }

  for (const line of markdown.split("\n")) {
    const match = line.match(/^#{2,3}\s+(.+)$/)
    if (match) {
      flush()
      heading = match[1].trim()
      continue
    }
    buffer.push(line)
  }
  flush()
  return sections
}

const STOP_WORDS = new Set(
  "a an and are as at be but by can do does for from has have how i if in is it its me my of on or our should so that the their them then there this to us was we what when where which who why will with you your".split(
    " "
  )
)

export function tokenize(text: string): string[] {
  return text
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .split(/[^a-z0-9]+/)
    .filter((token) => token.length > 1 && !STOP_WORDS.has(token))
}

/** Framework folders outrank per-client/per-listing pages on ties. */
function folderBoost(path: string): number {
  if (path === "BRAIN.md") return 1.5
  if (/^(ontology|playbooks|policies|skills|decisions|metrics|processes)\//.test(path)) return 1.35
  if (/^(review|funnel|stack|people|fleet|markets)\//.test(path)) return 1.15
  return 1
}

type IndexedChunk = {
  doc: WikifactorDoc
  chunk: WikifactorChunk
  terms: Map<string, number>
  length: number
  titleTerms: Set<string>
}

export type WikifactorIndex = {
  chunks: IndexedChunk[]
  documentFrequency: Map<string, number>
  averageLength: number
}

export function buildWikifactorIndex(corpus: WikifactorCorpus): WikifactorIndex {
  const chunks: IndexedChunk[] = []
  const documentFrequency = new Map<string, number>()
  let totalLength = 0

  for (const doc of corpus.docs) {
    const titleTerms = new Set(tokenize(`${doc.title} ${doc.path}`))
    for (const chunk of doc.chunks) {
      const tokens = tokenize(`${chunk.heading ?? ""} ${chunk.text}`)
      const terms = new Map<string, number>()
      for (const token of tokens) terms.set(token, (terms.get(token) ?? 0) + 1)
      for (const token of terms.keys()) {
        documentFrequency.set(token, (documentFrequency.get(token) ?? 0) + 1)
      }
      totalLength += tokens.length
      chunks.push({ doc, chunk, terms, length: tokens.length, titleTerms })
    }
  }

  return {
    chunks,
    documentFrequency,
    averageLength: chunks.length ? totalLength / chunks.length : 1,
  }
}

function excerpt(text: string, queryTerms: string[], maxChars = 900): string {
  if (text.length <= maxChars) return text
  const lower = text.toLowerCase()
  const first = queryTerms
    .map((term) => lower.indexOf(term))
    .filter((index) => index >= 0)
    .sort((a, b) => a - b)[0]
  const start = Math.max(0, (first ?? 0) - 200)
  return `${start > 0 ? "…" : ""}${text.slice(start, start + maxChars).trim()}…`
}

/** BM25 over heading-sized chunks, boosted for title/path matches and framework folders. */
export function searchWikifactor(
  index: WikifactorIndex,
  query: string,
  limit = 6
): WikifactorHit[] {
  const queryTerms = Array.from(new Set(tokenize(query)))
  if (queryTerms.length === 0) return []

  const k1 = 1.4
  const b = 0.75
  const total = index.chunks.length

  const scored = index.chunks.flatMap((entry) => {
    let score = 0
    let matched = 0
    for (const term of queryTerms) {
      const frequency = entry.terms.get(term) ?? 0
      const titleHit = entry.titleTerms.has(term)
      if (frequency === 0 && !titleHit) continue
      matched += 1
      const df = index.documentFrequency.get(term) ?? 0
      const idf = Math.log(1 + (total - df + 0.5) / (df + 0.5))
      const tf =
        (frequency * (k1 + 1)) /
        (frequency + k1 * (1 - b + (b * entry.length) / index.averageLength))
      score += idf * tf + (titleHit ? idf * 0.8 : 0)
    }
    if (score === 0) return []
    const coverage = matched / queryTerms.length
    return [{ entry, score: score * (0.5 + coverage) * folderBoost(entry.doc.path) }]
  })

  scored.sort((a, b) => b.score - a.score)

  const hits: WikifactorHit[] = []
  const perDoc = new Map<string, number>()
  for (const { entry, score } of scored) {
    const seen = perDoc.get(entry.doc.path) ?? 0
    if (seen >= 2) continue
    perDoc.set(entry.doc.path, seen + 1)
    hits.push({
      path: entry.doc.path,
      title: entry.doc.title,
      status: entry.doc.status,
      branch: entry.doc.branch,
      heading: entry.chunk.heading,
      excerpt: excerpt(entry.chunk.text, queryTerms),
      score: Math.round(score * 100) / 100,
    })
    if (hits.length >= limit) break
  }
  return hits
}

/** Full page text, capped so one read cannot flood the context window. */
export function readWikifactorDoc(
  corpus: WikifactorCorpus,
  docPath: string,
  maxChars = 14_000
): { path: string; title: string; status: WikifactorDoc["status"]; branch: string | null; text: string; truncated: boolean } | null {
  const normalized = docPath.replace(/^\/+/, "").replace(/^\[\[|\]\]$/g, "")
  const doc =
    corpus.docs.find((candidate) => candidate.path === normalized) ??
    corpus.docs.find((candidate) => candidate.path === `${normalized}.md`)
  if (!doc) return null
  const text = doc.chunks
    .map((chunk) => (chunk.heading ? `## ${chunk.heading}\n${chunk.text}` : chunk.text))
    .join("\n\n")
  return {
    path: doc.path,
    title: doc.title,
    status: doc.status,
    branch: doc.branch,
    text: text.slice(0, maxChars),
    truncated: text.length > maxChars,
  }
}
